import { promises as fs } from "node:fs";
import path from "node:path";
import { warn } from "../warn.js";
import { version } from "../version.js";
export const readReports = async (files) => {
    if (files.length === 0) {
        throw new Error("Empty file list");
    }
    return Promise.all(files.map(async (file) => {
        const textContent = await fs.readFile(file, { encoding: "utf-8" });
        const data = JSON.parse(textContent);
        return { file, data };
    }));
};
export const filterCompatibleReports = (fileContents) => {
    const compatible = fileContents.filter(({ file, data }) => {
        if (data.version === version)
            return true;
        warn(`Version in ${file} is not supported (${data.version}). Current version ${version}. Skipping...`);
        return false;
    });
    if (compatible.length === 0)
        throw new Error("No compatible reports found");
    return compatible;
};
export const warnAboutMixedSettings = (fileContents, sharedMetrics = false) => {
    const first = fileContents[0];
    for (const { file, data } of fileContents.slice(1)) {
        const differences = ["gzip", "brotli", "sourcemap"].filter((setting) => data.options[setting] !== first.data.options[setting]);
        if (differences.length > 0) {
            warn(`Settings in ${file} differ from ${first.file} (${differences.join(", ")}). ${sharedMetrics ? "Treemap v2 enables compressed metrics only when every input provides them; measurements may not be comparable." : `Using settings from ${first.file} for the merged report; measurements may not be comparable.`}`);
        }
    }
};
export const mergeReports = (fileContents) => {
    const tree = {
        name: "root",
        children: [],
    };
    const nodeParts = {};
    const nodeMetas = {};
    for (const { data } of fileContents) {
        if (data.tree.name === "root") {
            tree.children = tree.children.concat(data.tree.children);
        }
        else {
            tree.children.push(data.tree);
        }
        Object.assign(nodeParts, data.nodeParts);
        Object.assign(nodeMetas, data.nodeMetas);
    }
    const data = {
        version,
        tree,
        nodeParts,
        nodeMetas,
        env: fileContents[0].data.env,
        options: fileContents[0].data.options,
    };
    return data;
};
export const writeReport = async (filename, fileContent) => {
    await fs.mkdir(path.dirname(filename), { recursive: true });
    try {
        await fs.unlink(filename);
    }
    catch {
        // ignore
    }
    await fs.writeFile(filename, fileContent);
};
